"use client";

import { useState, useEffect } from "react";
import axios from "axios";
import { CheckCircle, AlertCircle, Loader2, Upload, Plus, Trash2 } from "lucide-react";
import Layout from "../../Layout";
import { useNavigate } from "react-router-dom";

export default function Delivery() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    nameSupplier: "",
    DateBon: new Date().toISOString().split("T")[0],
    bon: null,
    type: "Bon de livraison",
    products: [{
      productId: "",
      quantity: "",
      expirationDate: "",
      isNewProduct: false,
      nameProduct: "",
      priceForOne: "",
      amount: "0.00",
      unity: "unit",
      safetyThreshold: "",
      zoneId: "",
      numeroBielle: "",
    }],
  });
  const [suppliers, setSuppliers] = useState([]);
  const [productsList, setProductsList] = useState([]);
  const [zones, setZones] = useState([]);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [previewImage, setPreviewImage] = useState(null);

  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    setIsLoading(true);
    const token = localStorage.getItem("token");
    const role = localStorage.getItem("role");
    try {
      const [suppliersRes, productsRes, zonesRes] = await Promise.all([
        axios.get(`${process.env.REACT_APP_API_URL}/api/suppliers`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${process.env.REACT_APP_API_URL}/api/products`, { headers: { Authorization: `Bearer ${token}` } }),
        axios.get(`${process.env.REACT_APP_API_URL}/api/zones`, { headers: { Authorization: `Bearer ${token}`, Role: role } }),
      ]);
      setSuppliers(suppliersRes.data);
      setProductsList(productsRes.data);
      setZones(zonesRes.data);
    } catch (err) {
      setError(err.response?.data?.message || "Erreur lors de la récupération des données");
    } finally {
      setIsLoading(false);
    }
  };

  const handleChange = (e, index) => {
    const { name, value, files } = e.target;
    if (index === undefined) {
      if (name === "bon" && files?.length > 0) {
        setFormData({ ...formData, bon: files[0] });
        const reader = new FileReader();
        reader.onloadend = () => setPreviewImage(reader.result);
        reader.readAsDataURL(files[0]);
      } else {
        setFormData({ ...formData, [name]: value });
      }
    } else {
      const updatedProducts = [...formData.products];
      updatedProducts[index][name] = value;

      if (name === "productId") {
        updatedProducts[index].isNewProduct = value === "create-new";
        if (!updatedProducts[index].isNewProduct) {
          updatedProducts[index].nameProduct = "";
          updatedProducts[index].priceForOne = "";
          updatedProducts[index].amount = "0.00";
          updatedProducts[index].unity = "unit";
          updatedProducts[index].safetyThreshold = "";
          updatedProducts[index].zoneId = "";
          updatedProducts[index].numeroBielle = "";
        }
      }

      if (name === "priceForOne" || name === "quantity") {
        const price = parseFloat(updatedProducts[index].priceForOne) || 0;
        const qty = parseInt(updatedProducts[index].quantity) || 0;
        updatedProducts[index].amount = (price * qty).toFixed(2);
      }

      setFormData({ ...formData, products: updatedProducts });
    }
  };

  const addProduct = () => {
    setFormData({
      ...formData,
      products: [...formData.products, {
        productId: "",
        quantity: "",
        expirationDate: "",
        isNewProduct: false,
        nameProduct: "",
        priceForOne: "",
        amount: "0.00",
        unity: "unit",
        safetyThreshold: "",
        zoneId: "",
        numeroBielle: "",
      }],
    });
  };

  const removeProduct = (index) => {
    const updatedProducts = formData.products.filter((_, i) => i !== index);
    setFormData({ ...formData, products: updatedProducts });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSuccess("");
    setIsSubmitting(true);

    const token = localStorage.getItem("token");
    const role = localStorage.getItem("role");

    try {
      if (!formData.nameSupplier || !formData.DateBon) {
        throw new Error("Fournisseur et Date du Bon sont requis");
      }

      const formDataToSend = new FormData();
      formDataToSend.append("nameSupplier", formData.nameSupplier);
      formDataToSend.append("DateBon", formData.DateBon);
      formDataToSend.append("type", formData.type);
      if (formData.bon) {
        formDataToSend.append("bon", formData.bon);
      }

      // Separate new products and existing products
      const newProducts = formData.products.filter(p => p.isNewProduct);
      const existingProducts = formData.products.filter(p => !p.isNewProduct);

      // Handle new products creation
      if (newProducts.length > 0) {
        const newProductsToSend = newProducts.map(product => {
          if (!product.nameProduct || !product.priceForOne || !product.quantity || !product.zoneId || !product.expirationDate) {
            throw new Error("Tous les champs des nouveaux produits sont requis");
          }
          return {
            nameProduct: product.nameProduct,
            priceForOne: parseFloat(product.priceForOne),
            quantity: parseInt(product.quantity),
            amount: parseFloat(product.amount),
            unity: product.unity,
            safetyThreshold: product.safetyThreshold ? parseInt(product.safetyThreshold) : undefined,
            zoneId: product.zoneId,
            expirationDate: product.expirationDate,
            numeroBielle: product.numeroBielle || undefined,
          };
        });

        formDataToSend.append("products", JSON.stringify(newProductsToSend));
        const createResponse = await axios.post(`${process.env.REACT_APP_API_URL}/api/products`, formDataToSend, {
          headers: {
            Authorization: `Bearer ${token}`,
            Role: role,
            "Content-Type": "multipart/form-data",
          },
        });

        const newlyCreatedProducts = createResponse.data.data || [];
        if (!Array.isArray(newlyCreatedProducts)) {
          console.warn("newlyCreatedProducts is not an array:", newlyCreatedProducts);
          setProductsList([...productsList]);
        } else {
          setProductsList([...productsList, ...newlyCreatedProducts]);
        }
      }

      // Handle existing products quantity updates
      if (existingProducts.length > 0) {
        const updatePromises = existingProducts.map(product => {
          if (!product.productId || !product.quantity || !product.expirationDate) {
            throw new Error("Tous les champs des produits existants sont requis");
          }
          const productFormData = new FormData();
          productFormData.append("quantity", product.quantity);
          productFormData.append("expirationDate", product.expirationDate);
          productFormData.append("nameSupplier", formData.nameSupplier);
          productFormData.append("DateBon", formData.DateBon);
          productFormData.append("type", formData.type);
          if (formData.bon) {
            productFormData.append("bon", formData.bon);
          }

          return axios.put(
            `${process.env.REACT_APP_API_URL}/api/products/add-quantity/${product.productId}`,
            productFormData,
            {
              headers: {
                Authorization: `Bearer ${token}`,
                "Content-Type": "multipart/form-data",
              },
            }
          );
        });

        await Promise.all(updatePromises);
      }

      setSuccess("Livraison enregistrée avec succès !");
      setTimeout(() => {
        navigate("/ManageProducts");
      }, 1500);
    } catch (err) {
      setError(err.response?.data?.message || err.message || "Erreur lors de l'enregistrement de la livraison");
      console.error("Erreur Frontend :", err.response?.data || err);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <Layout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <h2 className="text-2xl font-bold tracking-tight">Nouvelle Livraison</h2>
            <p className="text-white/80 mt-1 text-sm">Ajoutez une nouvelle livraison de produits</p>
          </div>

          {(error || success) && (
            <div className={`m-6 p-4 ${error ? "bg-red-50" : "bg-green-50"} border-l-4 ${error ? "border-red-500" : "border-green-500"} rounded-r-lg flex items-center gap-3`}>
              {error ? <AlertCircle className="h-5 w-5 text-red-500" /> : <CheckCircle className="h-5 w-5 text-green-500" />}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>{error || success}</p>
            </div>
          )}

          {isLoading ? (
            <div className="flex justify-center items-center h-64">
              <div className="flex flex-col items-center gap-2">
                <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                <p className="text-[#00717F] text-sm font-medium">Chargement des données...</p>
              </div>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="p-6 space-y-6">
              {/* Delivery Information */}
              <div className="bg-[#F5F6FA]/50 p-6 rounded-xl border border-[#C8A45D/30]/50">
                <h3 className="text-lg font-medium text-[#00717F] mb-4">Informations de Livraison</h3>
                <div className="grid md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Fournisseur</label>
                    <select name="nameSupplier" value={formData.nameSupplier} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required>
                      <option value="">Sélectionner un fournisseur</option>
                      {suppliers.map((supplier) => (
                        <option key={supplier._id} value={`${supplier.firstName} ${supplier.lastName}`}>
                          {supplier.firstName} {supplier.lastName}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Date du Bon</label>
                    <input type="date" name="DateBon" value={formData.DateBon} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Type de Bon</label>
                    <select name="type" value={formData.type} onChange={handleChange} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg">
                      <option value="Bon de livraison">Bon de livraison</option>
                      <option value="Bon de sortie">Bon de sortie</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Bon</label>
                    <div className="flex items-center justify-center w-full">
                      <label className="flex flex-col items-center justify-center w-full h-12 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer bg-gray-50 hover:bg-gray-100">
                        <div className="flex flex-col items-center justify-center">
                          {previewImage ? (
                            <img src={previewImage} alt="Aperçu" className="h-10 object-contain" />
                          ) : (
                            <>
                              <Upload className="w-4 h-4 text-gray-500" />
                              <p className="text-sm text-gray-500">Cliquez ou glissez une image ici</p>
                            </>
                          )}
                        </div>
                        <input type="file" name="bon" accept="image/*" onChange={handleChange} className="hidden" />
                      </label>
                    </div>
                  </div>
                </div>
              </div>

              {/* Products Section */}
              {formData.products.map((product, index) => {
                const selectedProduct = productsList.find(p => p._id === product.productId);
                return (
                  <div key={index} className="bg-[#F5F6FA]/50 p-6 rounded-xl border border-[#C8A45D/30]/50 relative">
                    <button type="button" onClick={() => removeProduct(index)} className="absolute top-4 right-4 text-red-600 hover:text-red-800" disabled={formData.products.length === 1}>
                      <Trash2 className="h-5 w-5" />
                    </button>
                    <h3 className="text-lg font-medium text-[#00717F] mb-4">Produit {index + 1}</h3>
                    <div className="grid md:grid-cols-2 gap-6">
                      <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-1">Produit</label>
                        <select name="productId" value={product.productId} onChange={(e) => handleChange(e, index)} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required>
                          <option value="">Sélectionner un produit</option>
                          {productsList.map((prod) => (
                            <option key={prod._id} value={prod._id}>{prod.nameProduct}</option>
                          ))}
                          <option value="create-new">Créer un nouveau produit</option>
                        </select>
                      </div>

                      {product.isNewProduct ? (
                        <>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Nom du Produit</label>
                            <input type="text" name="nameProduct" value={product.nameProduct} onChange={(e) => handleChange(e, index)} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Prix Unitaire</label>
                            <div className="relative">
                              <input type="number" name="priceForOne" value={product.priceForOne} onChange={(e) => handleChange(e, index)} className="w-full pl-4 pr-8 py-2.5 border border-gray-300 rounded-lg" min="0" step="0.01" required />
                              <span className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500">DH</span>
                            </div>
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Quantité</label>
                            <input type="number" name="quantity" value={product.quantity} onChange={(e) => handleChange(e, index)} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" min="0" required />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Montant (Calculé)</label>
                            <div className="relative">
                              <input type="text" name="amount" value={product.amount} className="w-full pl-4 pr-8 py-2.5 border border-gray-300 rounded-lg bg-gray-50 text-gray-500" readOnly />
                              <span className="absolute right-3 top-1/2 transform -translate-y-1/2 text-gray-500">DH</span>
                            </div>
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Unité</label>
                            <select name="unity" value={product.unity} onChange={(e) => handleChange(e, index)} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg">
                              <option value="kg">kg</option>
                              <option value="g">g</option>
                              <option value="unit">unité</option>
                              <option value="liter">litre</option>
                              <option value="ml">ml</option>
                            </select>
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Seuil de Sécurité</label>
                            <input type="number" name="safetyThreshold" value={product.safetyThreshold} onChange={(e) => handleChange(e, index)} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" min="0" />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Zone</label>
                            <select name="zoneId" value={product.zoneId} onChange={(e) => handleChange(e, index)} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required>
                              <option value="">Sélectionner une zone</option>
                              {zones.map((zone) => (
                                <option key={zone._id} value={zone._id}>{zone.zoneName}</option>
                              ))}
                            </select>
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Date d'Expiration</label>
                            <input type="date" name="expirationDate" value={product.expirationDate} onChange={(e) => handleChange(e, index)} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Numéro de Bielle</label>
                            <input type="text" name="numeroBielle" value={product.numeroBielle} onChange={(e) => handleChange(e, index)} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" />
                          </div>
                        </>
                      ) : selectedProduct ? (
                        <>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Quantité Actuelle</label>
                            <input type="number" value={selectedProduct.quantity} disabled className="w-full px-4 py-2.5 border border-gray-300 rounded-lg bg-gray-100" />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Quantité à Ajouter</label>
                            <input type="number" name="quantity" value={product.quantity} onChange={(e) => handleChange(e, index)} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" min="1" required />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Nouveau Total (Calculé)</label>
                            <input type="text" value={(selectedProduct.quantity + (parseInt(product.quantity) || 0))} disabled className="w-full px-4 py-2.5 border border-gray-300 rounded-lg bg-gray-100" />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Unité</label>
                            <input type="text" value={selectedProduct.unity} disabled className="w-full px-4 py-2.5 border border-gray-300 rounded-lg bg-gray-100" />
                          </div>
                          <div>
                            <label className="block text-sm font-medium text-gray-700 mb-1">Date d'Expiration</label>
                            <input type="date" name="expirationDate" value={product.expirationDate} onChange={(e) => handleChange(e, index)} className="w-full px-4 py-2.5 border border-gray-300 rounded-lg" required />
                          </div>
                        </>
                      ) : null}
                    </div>
                  </div>
                );
              })}

              <div className="flex justify-between p-6">
                <button type="button" onClick={addProduct} className="px-5 py-2.5 bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white rounded-lg hover:bg-[#C8A45D] flex items-center gap-2 font-medium">
                  <Plus className="h-4 w-4" /> Ajouter un Produit
                </button>
                <div className="flex gap-4">
                  <button type="button" onClick={() => navigate("/ManageProducts")} className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50">
                    Annuler
                  </button>
                  <button type="submit" disabled={isSubmitting} className="px-4 py-2 bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white rounded-lg hover:opacity-90 flex items-center gap-2">
                    {isSubmitting ? (
                      <>
                        <Loader2 className="h-4 w-4 animate-spin" /> Traitement...
                      </>
                    ) : (
                      "Enregistrer Livraison"
                    )}
                  </button>
                </div>
              </div>
            </form>
          )}
        </div>
      </div>
    </Layout>
  );
}
